// Changing behaviour needs a NEW id: re-creating a deleted channel restores the user's old settings
private const val CH_DELIVERY = "delivery_v2"

// App-level and channel-level blocking are two different questions
fun canNotifyDelivery(ctx: Context): Boolean {
  val nm = NotificationManagerCompat.from(ctx)
  if (!nm.areNotificationsEnabled()) return false
  val channel = nm.getNotificationChannelCompat(CH_DELIVERY) ?: return false
  return channel.importance != NotificationManagerCompat.IMPORTANCE_NONE
}

