  override fun onCreate(savedInstanceState: Bundle?) {
    super.onCreate(savedInstanceState)
    handle(intent)
  }
  override fun onNewIntent(intent: Intent) {        // an already-running task lands here
    super.onNewIntent(intent)
    handle(intent)
  }
  private fun handle(intent: Intent) {
    if (intent.getBooleanExtra("from_notification", false)) analytics.log("notification_open")
    intent.data?.let(navigator::openDeepLink)       // logging after the screen, not before it
