private const val KEY_REPLY = "key_reply"

// WRONG: immutable, so the system has nowhere to put the typed text
val broken = PendingIntent.getBroadcast(
  ctx, convId, Intent(ctx, ReplyReceiver::class.java), PendingIntent.FLAG_IMMUTABLE
)

// RIGHT: mutable, with a request code unique per conversation
val replyIntent = PendingIntent.getBroadcast(
  ctx, convId,
  Intent(ctx, ReplyReceiver::class.java).putExtra("conv", convId),
  PendingIntent.FLAG_MUTABLE or PendingIntent.FLAG_UPDATE_CURRENT
)

val action = NotificationCompat.Action.Builder(R.drawable.ic_send, "Reply", replyIntent)
  .addRemoteInput(RemoteInput.Builder(KEY_REPLY).setLabel("Message").build())
  .setSemanticAction(NotificationCompat.Action.SEMANTIC_ACTION_REPLY)
  .setAllowGeneratedReplies(true)
  .build()

class ReplyReceiver : BroadcastReceiver() {
  override fun onReceive(ctx: Context, intent: Intent) {
    val text = RemoteInput.getResultsFromIntent(intent)
      ?.getCharSequence(KEY_REPLY) ?: return
    val convId = intent.getIntExtra("conv", 0)

    // Ten seconds at most in here — the real send belongs to WorkManager
    SendReplyWorker.enqueue(ctx, convId, text.toString())

    // Until a post lands on this id, the reply field stays stuck "sending"
    val updated = NotificationCompat.Builder(ctx, "chat")
      .setSmallIcon(R.drawable.ic_chat)
      .setStyle(messagingStyle(convId).addMessage(text, System.currentTimeMillis(), me))
      .setOnlyAlertOnce(true)
      .addAction(action)
      .build()
    NotificationManagerCompat.from(ctx).notify(convId, updated)
  }
}

