class AppMessagingService : FirebaseMessagingService() {
  // Fires on install, data clear, restore to a new device, and rotation —
  // often long before anyone has signed in.
  override fun onNewToken(token: String) {
    TokenStore.savePending(this, token)
    TokenUploadWorker.enqueue(this)     // retryable: the network may be gone
  }
}

// Every launch, not only at login: onNewToken is missed whenever the token
// changed while this process was not alive.
suspend fun syncToken(context: Context) {
  val token = FirebaseMessaging.getInstance().token.await()
  if (token != TokenStore.lastUploaded(context)) {
    TokenStore.savePending(context, token)
    TokenUploadWorker.enqueue(context)
  }
}

// WRONG: the previous user's token stays attached to this device
suspend fun signOutBroken(api: Api) {
  api.clearSession()
}

// RIGHT: drop the row server-side, then invalidate the instance token
suspend fun signOut(context: Context, api: Api) {
  api.deleteToken(TokenStore.lastUploaded(context))
  FirebaseMessaging.getInstance().deleteToken().await()
  TokenStore.clear(context)
}

