// One app-scoped holder, written only by the screen that is showing.
object VisibleConversation {
  @Volatile var id: String? = null
}

@Composable
fun ChatScreen(convId: String, vm: ChatViewModel) {
  val ctx = LocalContext.current
  val lifecycle = LocalLifecycleOwner.current.lifecycle
  DisposableEffect(convId, lifecycle) {
    val observer = LifecycleEventObserver { _, event ->
      when (event) {
        Lifecycle.Event.ON_RESUME -> {
          VisibleConversation.id = convId
          NotificationManagerCompat.from(ctx).cancel(convId.hashCode())
          vm.markRead()                       // and push the read receipt out
        }
        Lifecycle.Event.ON_PAUSE -> VisibleConversation.id = null
        else -> Unit
      }
    }
    lifecycle.addObserver(observer)
    onDispose { lifecycle.removeObserver(observer) }
  }
  MessageList(vm.messages.collectAsStateWithLifecycle().value)
}

// One place decides whether the system ever hears about this message.
class NotificationPresenter(private val ctx: Context) {
  fun post(message: Message) {
    val foreground = ProcessLifecycleOwner.get().lifecycle.currentState
      .isAtLeast(Lifecycle.State.RESUMED)

    when {
      VisibleConversation.id == message.convId -> return   // they are reading it
      foreground -> inAppBanners.tryEmit(message)          // elsewhere in the app
      else -> NotificationManagerCompat.from(ctx).notify(
        message.convId.hashCode(),                          // stable id per thread
        build(message).setOnlyAlertOnce(true).build()       // update, do not re-buzz
      )
    }
  }
}

// Android 14+: declaring the permission is no longer enough to hold it.
fun ensureFullScreenIntent(activity: Activity) {
  if (Build.VERSION.SDK_INT < Build.VERSION_CODES.UPSIDE_DOWN_CAKE) return
  val nm = activity.getSystemService(NotificationManager::class.java)
  if (nm.canUseFullScreenIntent()) return
  activity.startActivity(
    Intent(
      Settings.ACTION_MANAGE_APP_USE_FULL_SCREEN_INTENT,
      Uri.parse("package:" + activity.packageName)
    )
  )
}

