val calls = NotificationChannel("calls", "Incoming calls", NotificationManager.IMPORTANCE_HIGH)

fun incomingCall(ctx: Context, caller: Person, callId: Int): Notification {
  val answer = actionIntent(ctx, callId, CallAction.ANSWER)
  val decline = actionIntent(ctx, callId, CallAction.DECLINE)
  val screen = PendingIntent.getActivity(
    ctx, callId, Intent(ctx, CallActivity::class.java),
    PendingIntent.FLAG_IMMUTABLE or PendingIntent.FLAG_UPDATE_CURRENT
  )

  return NotificationCompat.Builder(ctx, "calls")
    .setSmallIcon(R.drawable.ic_call)
    .setStyle(NotificationCompat.CallStyle.forIncomingCall(caller, decline, answer))
    .setCategory(NotificationCompat.CATEGORY_CALL)
    .setOngoing(true)
    // A request, not a command: denied, or the screen unlocked, and this is
    // exactly the heads-up the user sees. Design for that case first.
    .setFullScreenIntent(screen, true)
    .build()
}

