// Segments 3 and 4, reported from the client with the ids the server logged.
class AppMessagingService : FirebaseMessagingService() {

  override fun onMessageReceived(message: RemoteMessage) {
    val nm = NotificationManagerCompat.from(this)
    val am = getSystemService(ActivityManager::class.java)
    val pm = getSystemService(PowerManager::class.java)

    analytics.log(
      "push_received",
      mapOf(
        "message_id" to message.messageId,
        "lag_ms" to (System.currentTimeMillis() - message.sentTime),
        // FCM throttling your high priority shows up right here
        "priority" to message.priority,
        "original_priority" to message.originalPriority,
        // The two fields that explain most "never arrived" tickets
        "notifications_enabled" to nm.areNotificationsEnabled(),
        "channel_importance" to (nm.getNotificationChannel("chat")?.importance ?: -1),
        // The two that expose an OEM battery manager, as a cohort
        "background_restricted" to am.isBackgroundRestricted,
        "battery_exempt" to pm.isIgnoringBatteryOptimizations(packageName)
      )
    )
    presenter.post(message)
    analytics.log("push_posted", message.messageId)   // segment 4 closed
  }
}

