// The public version is a real notification, not an apology for one.
private fun publicVersion(ctx: Context, tap: PendingIntent) =
  NotificationCompat.Builder(ctx, "security")
    .setSmallIcon(R.drawable.ic_lock)
    .setContentTitle("Acme")
    .setContentText("New sign-in code")     // says what it is, never the code
    .setContentIntent(tap)                  // same tap target, so nothing is lost
    .build()

fun otpNotification(ctx: Context, code: String, tap: PendingIntent): Notification =
  NotificationCompat.Builder(ctx, "security")
    .setSmallIcon(R.drawable.ic_lock)
    .setContentTitle("Sign-in code")        // NOT "Your code is 481920"
    .setContentText("Your code is " + code)
    .setContentIntent(tap)
    .setVisibility(NotificationCompat.VISIBILITY_PRIVATE)
    .setPublicVersion(publicVersion(ctx, tap))  // else: a bare "Contents hidden"
    .setTimeoutAfter(90_000)                    // expires with the code itself
    .setAutoCancel(true)
    .build()

// The channel carries the ceiling: set once at creation, then the user's to
// change. A per-notification visibility can only be equal or stricter.
val security = NotificationChannel(
  "security", "Sign-in", NotificationManager.IMPORTANCE_HIGH
).apply { lockscreenVisibility = Notification.VISIBILITY_PRIVATE }

